/* INPUT: PreVibe default light palette and semantic renderer states.
 * OUTPUT: one flat desktop workspace; responsive reflow and accessible interaction.
 * POS: renderer design tokens and component styles. See ./AGENTS.md and ../../DESIGN.md. */
:root {
  color-scheme: light;
  font-family: 'Inter', 'SF Pro Display', 'PingFang SC', system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  font-size: 14px; font-synthesis: none;
  --ground: #edf1f5; --surface: #f7f9fc; --surface-muted: #e8edf3;
  --text: #1f2937; --muted: #596579; --line: #cbd3dd; --control-line: #a7b2c0;
  --hover: rgba(96,112,131,.14); --active: rgba(96,112,131,.24);
  --accent: #424a57; --accent-hover: #303a49; --focus: #2866b4;
  --tint: #e7edf5; --success: #266247; --success-bg: #e5f0e9;
  --warning: #825711; --warning-bg: #fff3db; --danger: #9c392f; --danger-bg: #faeae6;
  --radius-control: 10px; --radius-row: 8px; --radius-button: 12px;
  --mail-columns: 36px minmax(180px,1.7fr) minmax(100px,.85fr) 100px minmax(125px,1fr) minmax(130px,1fr);
  color: var(--text); background: var(--ground);
}
* { box-sizing: border-box; }button { display: inline-flex; align-items: center; justify-content: center; gap: 6px; min-height: 36px; padding: 7px 12px; border: 1px solid var(--line); border-radius: var(--radius-button); background: var(--surface-muted); color: var(--text); font-weight: 500; cursor: pointer; line-height: 1.4; transition: background-color 160ms ease, border-color 160ms ease, color 160ms ease; }.primary { background: var(--accent); border-color: var(--accent); color: #fff; }.primary:hover:not(:disabled) { background: var(--accent-hover); border-color: var(--accent-hover); }button:disabled { color: #687485; background: #e9edf2; border-color: #d6dde5; cursor: default; }:where(button,input,textarea,select,summary,[tabindex]):focus-visible { outline: 2px solid var(--focus); outline-offset: 3px; }

